mapper.update:
UPDATE portfolio_guide SET guide_content = CAST(#{guideContent, jdbcType=VARCHAR} AS JSONB), completion_percentage = #{completionPercentage}, current_step = #{currentStep},
is_completed = #{isCompleted},
updated_at = NOW() WHERE guide_id = #{guideId}

UPDATE portfolio_guide SET guide_feedback = CAST(#{guideFeedback, jdbcType=VARCHAR} AS JSONB),
updated_at = NOW()
WHERE guide_id = #{guideId}
